// Self-referential struct — must use 'struct Node' inside
typedef struct Node {
    int data;
    struct Node *next;
} Node;

// Push to front of list
void push(Node **head, int val) {
    Node *n = malloc(sizeof(Node));
    if (!n) return;
    n->data = val;
    n->next = *head;   // new node points to old head
    *head = n;         // head now points to new node
}

// Print list
void print_list(Node *head) {
    while (head != NULL) {
        printf("%d -> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

// Free entire list
void free_list(Node *head) {
    while (head) {
        Node *tmp = head;
        head = head->next;
        free(tmp);
    }
}

int main(void) {
    Node *head = NULL;
    push(&head, 1);
    push(&head, 2);
    push(&head, 3);
    print_list(head);   // 3 -> 2 -> 1 -> NULL
    free_list(head);
    return 0;
}
```

