#include <stdlib.h>
#include <string.h>

// Allocate rows×cols matrix
int **alloc_matrix(int rows, int cols) {
    // Allocate array of row pointers
    int **m = malloc(rows * sizeof(int*));
    if (!m) return NULL;
    for (int i = 0; i < rows; i++) {
        m[i] = malloc(cols * sizeof(int));
        if (!m[i]) { /* handle error */ }
        memset(m[i], 0, cols * sizeof(int));  // zero-initialize
    }
    return m;
}

// Free the matrix
void free_matrix(int **m, int rows) {
    for (int i = 0; i < rows; i++) free(m[i]);  // free each row
    free(m);                                      // free the pointer array
}

// Usage
