```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int val; struct Node *next; } Node;
typedef struct { Node *top; int size; } Stack;

void stack_push(Stack *s, int val) {
    Node *n = malloc(sizeof(Node));
    if (!n) return;
    n->val = val;
    n->next = s->top;
    s->top = n;
    s->size++;
}

int stack_pop(Stack *s) {
    if (!s->top) return -1;  // empty
    int v = s->top->val;
    Node *t = s->top;
    s->top = t->next;
    free(t);
    s->size--;
    return v;
}

int stack_peek(const Stack *s) {
    return s->top ? s->top->val : -1;
}

int main(void) {
    Stack s = {NULL, 0};
    stack_push(&s, 1);
    stack_push(&s, 2);
    stack_push(&s, 3);
    printf("%d\n", stack_pop(&s));  // 3
    printf("%d\n", stack_pop(&s));  // 2
    return 0;
}
```

```c
// Binary search — array must be sorted!
int bsearch_int(const int *arr, int n, int target) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;  // avoids integer overflow vs (lo+hi)/2
        if (arr[mid] == target) return mid;   // found
        if (arr[mid] < target) lo = mid + 1; // target is in right half
        else                   hi = mid - 1; // target is in left half
    }
    return -1;  // not found
}

int main(void) {
    int arr[] = {1, 3, 5, 7, 9, 11, 13};
    int n = sizeof(arr) / sizeof(arr[0]);
    printf("%d\n", bsearch_int(arr, n, 7));   // 3 (index)
    printf("%d\n", bsearch_int(arr, n, 6));   // -1 (not found)
    return 0;
}
```

Time complexity: O(log n). The stdlib also provides `bsearch()` which works with `void*` for any type.

**Custom quicksort:**
```c
void quicksort(int *arr, int lo, int hi) {
    if (lo >= hi) return;
    int pivot = arr[hi], i = lo - 1;
    for (int j = lo; j < hi; j++) {
        if (arr[j] <= pivot) {
            int t = arr[++i]; arr[i] = arr[j]; arr[j] = t;  // swap
        }
    }
    int t = arr[++i]; arr[i] = arr[hi]; arr[hi] = t;  // place pivot
    quicksort(arr, lo, i - 1);
    quicksort(arr, i + 1, hi);
}

// Call:
int arr[] = {5, 2, 8, 1, 9};
quicksort(arr, 0, 4);
```

